      "title": "ODR: почему заголовок проверяется не только внутри одного .cpp",
      "lead": "Если заголовок прочитали два .cpp, одинаковый текст оказался в двух отдельных компиляциях. Почему определение класса так размещают, а тело обычной функции — не всегда?",
