          "type": "text",
          "html": "В заголовке примера написано <code>inline</code>. При соблюдении требований ODR это позволяет одной функции иметь согласованные определения в разных единицах трансляции. Ожидаемый вывод собранных двух .cpp — <code>42 6</code>. Ключевое слово не заставляет компилятор подставить тело вместо вызова и не обещает ускорения. Без него данный способ размещения обычной внешней функции нарушает правило; GNU ld обычно сообщает <code>multiple definition</code>."
