          "type": "note",
          "kind": "tip",
          "html": "Основание разделения требований линковки: <a href=\"https://cmake.org/cmake/help/v3.28/manual/cmake-generator-expressions.7.html\">CMake 3.28, LINK_ONLY</a>. Документация описывает закрытые зависимости линковки без передачи прочих требований, например каталогов заголовков."
